pub const ACCOUNT_HELP: &str = "Before you begin:\n  1. In Grocy, an administrator can create a dedicated Hermes user under Manage users.\n  2. Grant only the household features you want Hermes to use. API keys inherit this user's permissions. Some custom-field/entity administration may require broader Grocy permissions.\n  3. Sign in as that user. Open the user menu > Manage API keys > Add, and copy its key. Use an API key, not your account password.\n  4. Strongly recommend 2FA for your identity-provider account where available (for example Authelia). An API key can bypass frontend 2FA; protect and revoke it separately.\n\nHermes and its model provider can retain returned household data in history. This MCP does not keep a household-data cache.\n";
pub const WALLET_HELP: &str = "Protect your desktop wallet before storing the Grocy key.\nKDE: open KWallet Manager, open your default wallet (often kdewallet), and use File > Change Password. Set a non-empty password and keep the wallet enabled. Open/unlock it in the manager before using Hermes. KWallet's file format cannot prove whether its password is empty.\nGNOME: open Passwords and Keys (Seahorse), select the default keyring, and choose Change Password. Set a non-empty password and unlock it.\nOther Secret Service providers: protect and unlock the default collection in that provider's own manager.\nEncrypted application-to-wallet communication is always required, even if you accept unsafe storage.\n";
pub fn detected_timezone() -> Option<String> {
    let link = std::fs::read_link("/etc/localtime").ok()?;
    let text = link.to_string_lossy();
    text.split_once("zoneinfo/").map(|(_, s)| s.to_owned())
}
